#!/usr/bin/env python3
"""Generate the legacy requirements file from project dependency metadata."""
import argparse
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:
    import tomli as tomllib


ROOT = Path(__file__).resolve().parents[2]


def render_requirements():
    with (ROOT / "pyproject.toml").open("rb") as source:
        project = tomllib.load(source)["project"]
    lines = [
        "# Generated from pyproject.toml; do not edit this file directly.",
        "# Regenerate with: python .github/scripts/update_requirements.py",
        "# Includes all optional features for legacy source installations.",
        "",
        "# Required by the CLI commands",
        *project["dependencies"],
    ]
    for extra, requirements in project.get("optional-dependencies", {}).items():
        lines.extend(["", f"# Optional feature: {extra}", *requirements])
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if requirements.txt is out of date")
    args = parser.parse_args()
    target = ROOT / "requirements.txt"
    expected = render_requirements()
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != expected:
            parser.exit(1, "requirements.txt is out of date; run python .github/scripts/update_requirements.py\n")
    else:
        target.write_text(expected, encoding="utf-8")


if __name__ == "__main__":
    main()
